/**
 * examPrep.controller.js — Exam Prep v3
 * Contract: _contracts/01-exam-prep.md
 *
 * Three things a student can do:
 *   A. AIBE (Bar Council) — a FULL 100-MCQ paper across the official subject
 *      weightage, 210-minute timer, +1 per correct answer, no negative marking,
 *      pass 45%. Generated by AI in batches; graded deterministically with ZERO
 *      AI calls. Correct answers never leave the server until submission.
 *   B. SPPU (University) — a FULL 80-mark written paper (Part A 3x15, Part B
 *      2x10, Part C 3x5), 180-minute timer. AI generates the paper AND grades
 *      each answer against a marking scheme the student never sees beforehand.
 *   C. Library — browse/download past question papers (S3) + official sources.
 *
 * THINGS THAT ARE DELIBERATE HERE (do not "simplify" them back):
 *  - The model is NEVER named in this file. Everything goes through
 *    generateText() in services/gemini.service.js, which reads
 *    process.env.GEMINI_MODEL. A hardcoded model id is how you get a silent
 *    404 in production the day the model name changes.
 *  - exam_attempts is RLS-protected, so every read/write of it goes through
 *    queryAsCollege(college_id, ...). Plain pool.query on that table would
 *    bypass row-level security. pool.query is used ONLY for exam_papers and
 *    ai_usage_log, neither of which has a college_id or an RLS policy.
 *  - The timer is enforced from expires_at stored in the DB, not from anything
 *    the client sends. But a late submission is still GRADED and SAVED (flagged
 *    expired) — throwing away a student's three hours of work over a network
 *    hiccup is a worse failure than an untimed score.
 *  - 100 MCQs is ~11,000 output tokens, which no single response can carry.
 *    Generation is batched, and finishReason === 'MAX_TOKENS' means the batch
 *    was truncated — it is retried larger, never silently trusted.
 */
const AWS = require('aws-sdk');
const { pool, queryAsCollege } = require('../config/db');
const { generateText } = require('../services/gemini.service');

const s3 = new AWS.S3({ region: process.env.AWS_REGION, signatureVersion: 'v4' });
const BUCKET = process.env.S3_BUCKET_FILES;

const DISCLAIMER = 'For educational purposes only. Verify with a qualified advocate.';
const PRACTICE_NOTE = 'AI-generated practice paper — not an official exam paper.';
// Split limits, founder decision 2026-07-28 (was a single shared 30/month).
// Two SEPARATE Redis counters, so exhausting AIBE cannot take a student's
// university papers with it — and, more to the point, a student can no longer
// spend all 30 on AIBE, which is the expensive one (Rs 1.12 vs Rs 0.35 a
// paper — MEASURED on staging 2026-07-28, not estimated). That single change
// drops the worst case from Rs 11,729 to Rs 7,718 at 350 students.
// Must match featureLimitMonthly() in the routes file.
const AIBE_MONTHLY_LIMIT = 25;
const SPPU_MONTHLY_LIMIT = 25;
const CHARS_PER_TOKEN = 4;
const LATE_GRACE_MS = 120 * 1000;  // network slack on a timed submission

// ── AIBE: official subject weightage. Weights are question counts and MUST sum
//    to exactly 100 — the partner draft's 11-subject table summed to 92, which
//    would have produced a 92-question "100-question paper". Asserted below.
const AIBE = {
  passGeneralPct: 45,
  passReservedPct: 40,
  totalQuestions: 100,
  durationMin: 210,
  subjects: [
    ['Constitutional Law', 10],
    ['Code of Criminal Procedure / BNSS', 10],
    ['Code of Civil Procedure', 10],
    ['Indian Penal Code / BNS', 8],
    ['Law of Evidence / BSA', 8],
    ['Family Law', 8],
    ['Contract, Specific Relief, Property & Negotiable Instruments', 8],
    ['Law of Tort, Motor Vehicles & Consumer Protection', 5],
    ['Professional Ethics & BCI Rules', 4],
    ['Alternative Dispute Resolution', 4],
    ['Public Interest Litigation', 4],
    ['Labour & Industrial Law', 4],
    ['Law related to Taxation', 4],
    ['Administrative Law', 3],
    ['Company Law', 2],
    ['Environmental Law', 2],
    ['Cyber Law', 2],
    ['Land Acquisition Act', 2],
    ['Intellectual Property Law', 2],
  ],
};

// Fail loudly at boot rather than shipping a 92-question paper called "100".
{
  const sum = AIBE.subjects.reduce((n, [, w]) => n + w, 0);
  if (sum !== AIBE.totalQuestions) {
    throw new Error(`AIBE weightage sums to ${sum}, expected ${AIBE.totalQuestions}`);
  }
}

// ── SPPU: the 80-mark written paper structure. The other 20 marks of the SPPU
//    100 are internal assessment at the college and are not examinable here.
const SPPU = {
  durationMin: 180,
  totalMarks: 80,
  parts: [
    { part: 'A', label: 'Long answer', count: 3, marks: 15, maxWords: 300 },
    { part: 'B', label: 'Short notes', count: 2, marks: 10, maxWords: 200 },
    { part: 'C', label: 'Short answer', count: 3, marks: 5, maxWords: 120 },
  ],
};
const SPPU_TOTAL_Q = SPPU.parts.reduce((n, p) => n + p.count, 0);

// ── SPPU program → year → semester → subjects (2017 Pattern / July 2019
//    amendment). The LAW papers are SHARED: BA LLB Sem V-X == LLB Sem I-VI.
const LAW_SEMS = {
  1: ['Legal and Constitutional History', 'Family Law I', 'Law of Contract I', 'Law of Crimes', 'Optional Paper I'],
  2: ['Constitutional Law I', 'Family Law II', 'Law of Contract II', 'Tort and Consumer Protection Law', 'Optional Paper II'],
  3: ['Constitutional Law II', 'Property Law and Easement', 'Public International Law', 'Professional Ethics and Contempt of Court Law', 'Optional Paper III'],
  4: ['Labour and Industrial Law', 'Jurisprudence', 'Law of Evidence', 'Alternate Dispute Resolution System', 'Optional Paper IV'],
  5: ['Civil Procedure Code', 'Interpretation of Statutes', 'Environmental Law', 'Drafting, Pleading and Conveyance', 'Optional Paper V'],
  6: ['Criminal Procedure Code', 'Administrative Law', 'Company Law', 'Moot Court Exercise and Internship', 'Optional Paper VI'],
};
const PROGRAMS = {
  llb_3yr: { label: 'LLB (3-year)', years: 3, sems: LAW_SEMS },
  ballb_5yr: {
    label: 'BA LLB (5-year)',
    years: 5,
    sems: {
      1: ['General English', 'General Principles of Political Science', 'General Principles of Economics', 'General Principles of Sociology'],
      2: ['English for Law', 'Political Theories', 'Macro Economics, Policies and Practice', 'Theoretical Perspectives of Sociology'],
      3: ['Legal Language and Legal Reasoning', 'Public Policy and Public Administration', 'Theories of Development and Indian Economy', 'Society in India'],
      4: ['Law and Literature', 'International Relations', 'Law and Economics', 'Social Research Methods'],
      5: LAW_SEMS[1], 6: LAW_SEMS[2], 7: LAW_SEMS[3], 8: LAW_SEMS[4], 9: LAW_SEMS[5], 10: LAW_SEMS[6],
    },
  },
};

// Official / public sources where students can download SPPU past papers.
const LIBRARY_LINKS = [
  { label: 'SPPU (official university site) — Examination → old question papers', url: 'https://www.unipune.ac.in/', note: 'Authoritative source' },
  { label: 'SPPU Online — LLB question papers (semester-wise)', url: 'https://www.sppuonline.com/llb.html' },
  { label: 'Stupidsid — SPPU Law solved papers', url: 'https://stupidsid.com/solved-question-papers/sppu/law' },
  { label: 'GKPad — SPPU LLB previous-year papers', url: 'https://www.gkpad.com/sppu-llb-previous-year-papers/' },
  { label: 'Studocu — BA LLB previous-year papers', url: 'https://www.studocu.com/in/document/savitribai-phule-pune-university/ba-llb/previous-years-question-paper/41722394' },
  { label: 'KopyKitab — Pune University question papers (all courses)', url: 'https://www.kopykitab.com/blog/pune-university-question-papers/' },
];

// ── small helpers ────────────────────────────────────────────────────────────
const capTokens = (text, inTokens) => String(text || '').slice(0, inTokens * CHARS_PER_TOKEN);
const clampWords = (t, n) => String(t || '').trim().split(/\s+/).slice(0, n).join(' ');
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Gemini returns JSON wrapped in prose or code fences often enough that a bare
 * JSON.parse is a guaranteed 500 eventually. Pull the outermost {...} out.
 */
function parseJson(text) {
  const c = String(text).replace(/```json/gi, '').replace(/```/g, '').trim();
  const s = c.indexOf('{');
  const e = c.lastIndexOf('}');
  if (s === -1 || e === -1) throw new Error('no JSON object in model output');
  return JSON.parse(c.slice(s, e + 1));
}

// ai_usage_log has no RLS policy (fire-and-forget analytics write, not one of
// the RLS-protected tables) — plain pool.query, same as Drafting Lab.
//
// `calls` and `finishReason` added 2026-07-28. One Exam Prep row can represent
// many Gemini calls — AIBE generation is 9 batches, SPPU submit is up to 8
// gradings — so a row count is NOT a call count here, unlike every other
// feature. Without the explicit number the admin panel understates AIBE by 9:1.
// finishReason: 'MAX_TOKENS' means something was truncated and the output cap
// needs raising, which is otherwise invisible after the fact.
const logUsage = (user_id, college_id, model, tin, tout, calls = 1, finishReason = null) =>
  pool.query(
    `INSERT INTO ai_usage_log (user_id, college_id, feature_name, model, tokens_in, tokens_out, calls, finish_reason)
     VALUES ($1,$2,'exam_prep',$3,$4,$5,$6,$7)`,
    [user_id, college_id, model, tin, tout, calls, finishReason]
  ).catch((e) => console.error('ai_usage_log insert failed:', e.message));

// One row covers many calls, so the row's finish_reason must be the WORST of
// them, not the last. Taking the last hides a truncated batch 3 behind a clean
// batch 9 — which defeats the only reason the column exists.
const worstFinish = (a, b) =>
  (a === 'MAX_TOKENS' || b === 'MAX_TOKENS') ? 'MAX_TOKENS' : (b || a);

// exam_attempts IS RLS-protected — never pool.query here.
async function loadOwnAttempt(id, user_id, college_id) {
  // A malformed UUID makes Postgres throw 22P02 rather than return zero rows,
  // which would surface as a 500 on the "stupid path" test. Guard it.
  if (!UUID_RE.test(String(id || ''))) return null;
  const { rows } = await queryAsCollege(
    college_id,
    `SELECT * FROM exam_attempts WHERE attempt_id=$1 AND user_id=$2 AND college_id=$3`,
    [id, user_id, college_id]
  );
  return rows[0] || null;
}

/** Timer verdict for a submission. Never rejects — reports. */
function timerVerdict(meta) {
  const started = meta.started_at ? new Date(meta.started_at).getTime() : null;
  const expires = meta.expires_at ? new Date(meta.expires_at).getTime() : null;
  const now = Date.now();
  return {
    expired: Boolean(expires && now > expires + LATE_GRACE_MS),
    elapsedSec: started ? Math.max(0, Math.round((now - started) / 1000)) : null,
    durationMin: meta.duration_min ?? null,
  };
}

function stamps(durationMin) {
  const now = new Date();
  return {
    started_at: now.toISOString(),
    expires_at: new Date(now.getTime() + durationMin * 60 * 1000).toISOString(),
    duration_min: durationMin,
  };
}

// ── 1. structure ─────────────────────────────────────────────────────────────
const getStructure = async (req, res, next) => {
  try {
    res.json({
      // Kept as separate numbers rather than one total: the two are not
      // interchangeable, and showing "30/month" would promise a student
      // something the middleware will refuse.
      aibeMonthlyLimit: AIBE_MONTHLY_LIMIT,
      sppuMonthlyLimit: SPPU_MONTHLY_LIMIT,
      practiceNote: PRACTICE_NOTE,
      disclaimer: DISCLAIMER,
      aibe: {
        label: 'AIBE (Bar Council of India)',
        passGeneralPct: AIBE.passGeneralPct,
        passReservedPct: AIBE.passReservedPct,
        totalQuestions: AIBE.totalQuestions,
        durationMin: AIBE.durationMin,
        subjects: AIBE.subjects.map(([name, weight]) => ({ name, weight })),
      },
      sppu: {
        label: 'SPPU University Exam',
        totalMarks: SPPU.totalMarks,
        durationMin: SPPU.durationMin,
        parts: SPPU.parts,
        programs: Object.entries(PROGRAMS).map(([id, p]) => ({
          id, label: p.label, years: p.years, sems: p.sems,
        })),
      },
      libraryLinks: LIBRARY_LINKS,
    });
  } catch (err) { next(err); }
};

// ── 2. resume an in-progress paper (does NOT consume a monthly paper) ────────
const getActive = async (req, res, next) => {
  try {
    const { user_id, college_id } = req.user;
    const { rows } = await queryAsCollege(
      college_id,
      `SELECT attempt_id, exam_type, answers, created_at
         FROM exam_attempts
        WHERE user_id=$1 AND college_id=$2 AND score IS NULL
        ORDER BY created_at DESC
        LIMIT 1`,
      [user_id, college_id]
    );
    const a = rows[0];
    if (!a || !a.answers || a.answers.submitted) return res.json({ active: null });

    const meta = a.answers;
    const t = timerVerdict(meta);
    if (t.expired) return res.json({ active: null }); // nothing useful to resume

    if (meta.kind === 'aibe') {
      return res.json({
        active: {
          kind: 'aibe',
          paperId: a.attempt_id,
          expiresAt: meta.expires_at,
          durationMin: meta.duration_min,
          practiceNote: PRACTICE_NOTE,
          disclaimer: DISCLAIMER,
          passPct: AIBE.passGeneralPct,
          total: (meta.questions || []).length,
          // `correct` is stripped — it must not reach the browser before submit.
          questions: (meta.questions || []).map(({ q, options, subject }) => ({ q, options, subject })),
        },
      });
    }
    return res.json({
      active: {
        kind: 'sppu',
        paperId: a.attempt_id,
        expiresAt: meta.expires_at,
        durationMin: meta.duration_min,
        practiceNote: PRACTICE_NOTE,
        disclaimer: DISCLAIMER,
        program: PROGRAMS[meta.program]?.label || meta.program,
        semester: meta.sem,
        subject: meta.subject,
        totalMarks: SPPU.totalMarks,
        // `scheme` is stripped — the marking scheme stays server-side.
        questions: (meta.questions || []).map(({ q, marks, part, maxWords }) => ({ q, marks, part, maxWords })),
      },
    });
  } catch (err) { next(err); }
};

// ── 3A. AIBE — generate a full 100-question paper ────────────────────────────

/**
 * Group the 19 weighted subjects into batches of at most MAX_PER_BATCH
 * questions, so no single Gemini response has to carry all 100 MCQs
 * (~11,000 output tokens). Yields ~9 batches; each batch is one call.
 */
const MAX_PER_BATCH = 13;
function batchSubjects() {
  const batches = [];
  let cur = [];
  let n = 0;
  for (const [name, weight] of AIBE.subjects) {
    if (n + weight > MAX_PER_BATCH && cur.length) { batches.push(cur); cur = []; n = 0; }
    cur.push([name, weight]);
    n += weight;
  }
  if (cur.length) batches.push(cur);
  return batches;
}

function aibeBatchPrompt(batch) {
  const spec = batch.map(([s, w]) => `- ${s}: exactly ${w} question(s)`).join('\n');
  const total = batch.reduce((n, [, w]) => n + w, 0);
  return `You are setting questions for the All India Bar Examination (AIBE) in India.
Write ${total} multiple-choice questions, distributed exactly as follows:
${spec}

Rules:
- Use CURRENT Indian law, including the Bharatiya Nyaya Sanhita (BNS), Bharatiya Nagarik
  Suraksha Sanhita (BNSS) and Bharatiya Sakshya Adhiniyam (BSA), 2023.
- Exactly 4 options per question, exactly one correct.
- AIBE is open-book and practical: prefer applied, section-based questions over trivia.
- Keep each question under 45 words and each option under 20 words.
- Vary which option index is the correct one.

Return STRICT JSON only, no prose, no markdown:
{"questions":[{"q":"...","options":["...","...","...","..."],"correct":0,"subject":"<exact subject name from the list above>"}]}
Exactly ${total} questions. JSON only.`;
}

function normaliseMcqs(parsed, subjectNames) {
  return (parsed.questions || [])
    .map((q) => ({
      q: String(q.q || '').slice(0, 500),
      options: (Array.isArray(q.options) ? q.options : []).slice(0, 4).map((o) => String(o).slice(0, 220)),
      correct: Math.max(0, Math.min(3, Number.isFinite(Number(q.correct)) ? Number(q.correct) : 0)),
      subject: subjectNames.includes(String(q.subject)) ? String(q.subject) : (subjectNames[0] || 'General'),
    }))
    .filter((q) => q.q && q.options.length === 4 && q.options.every(Boolean));
}

const aibeGenerate = async (req, res, next) => {
  const { user_id, college_id } = req.user;
  try {
    const batches = batchSubjects();
    let questions = [];
    let tinAll = 0, toutAll = 0, modelUsed = null;
    // Real Gemini call count, not batch count — a batch that hits MAX_TOKENS
    // and retries is two calls, and the cost panel should say so.
    let callsAll = 0, lastFinish = null;

    // Batches run in small waves rather than all at once: 9 simultaneous Gemini
    // calls per student across 350 students is exactly how you earn a 429 storm.
    const WAVE = 3;
    for (let i = 0; i < batches.length; i += WAVE) {
      const wave = batches.slice(i, i + WAVE);
      const settled = await Promise.all(wave.map(async (batch) => {
        const names = batch.map(([s]) => s);
        const ask = (outCap, timeoutMs) => generateText({
          prompt: capTokens(aibeBatchPrompt(batch), 900),
          maxOutputTokens: outCap,
          // High temperature on purpose: an identical prompt at low temperature
          // returns the same canonical questions every time — the exact defect
          // found in AI Interviewer v4.
          temperature: 0.9,
          timeoutMs,
        });
        try {
          let out = await ask(1700, 30000);
          let calls = 1;
          // Google bills the truncated attempt too. Carry its tokens forward or
          // the log understates a retry by a whole call — measured 2026-07-28:
          // row 265 reported calls=10 with the same tokens_in as the 9-call
          // row 264, which is arithmetically impossible and was this bug.
          let tin = out.tokensIn || 0, tout = out.tokensOut || 0;
          let finish = out.finishReason || null;
          // MAX_TOKENS means the JSON array was cut mid-object, so the batch
          // would parse short or not at all. Retry once with more room.
          if (out.finishReason === 'MAX_TOKENS') {
            out = await ask(2100, 35000);
            calls = 2;
            tin += out.tokensIn || 0;
            tout += out.tokensOut || 0;
          }
          return { out, names, calls, tin, tout, finish };
        } catch (e) {
          console.error('AIBE batch failed:', e.message);
          // A batch that threw may still have been billed, but we have no token
          // figures for it — count the attempt so the call number is not a lie.
          return { failedCalls: 1 };
        }
      }));

      for (const s of settled) {
        if (!s) continue;
        if (s.failedCalls) { callsAll += s.failedCalls; continue; }
        tinAll += s.tin || 0;
        toutAll += s.tout || 0;
        callsAll += s.calls;
        lastFinish = worstFinish(lastFinish, s.finish);
        modelUsed = s.out.model || modelUsed;
        try {
          questions = questions.concat(normaliseMcqs(parseJson(s.out.text), s.names));
        } catch (e) {
          console.error('AIBE batch parse failed:', e.message);
        }
      }
    }

    // Cost is incurred whether or not the paper is usable — log it either way.
    if (tinAll || toutAll) logUsage(user_id, college_id, modelUsed, tinAll, toutAll, callsAll, lastFinish);

    // A partial paper is worse than an honest failure: the student would sit a
    // "100-question" exam of 40 questions and think their percentage meant
    // something. 90 is the floor.
    if (questions.length < Math.floor(AIBE.totalQuestions * 0.9)) {
      return res.status(502).json({
        error: 'Could not build a full paper right now. Please try again in a moment.',
      });
    }
    questions = questions.slice(0, AIBE.totalQuestions);

    const meta = {
      kind: 'aibe',
      questions,
      submitted: false,
      ...stamps(AIBE.durationMin),
    };
    const { rows } = await queryAsCollege(
      college_id,
      `INSERT INTO exam_attempts (user_id, college_id, exam_type, answers)
       VALUES ($1,$2,'aibe',$3) RETURNING attempt_id`,
      [user_id, college_id, JSON.stringify(meta)]
    );

    res.json({
      paperId: rows[0].attempt_id,
      practiceNote: PRACTICE_NOTE,
      disclaimer: DISCLAIMER,
      passPct: AIBE.passGeneralPct,
      passReservedPct: AIBE.passReservedPct,
      durationMin: AIBE.durationMin,
      expiresAt: meta.expires_at,
      total: questions.length,
      usedThisMonth: req.featureUsageCount ?? null,
      monthlyLimit: AIBE_MONTHLY_LIMIT,
      // `correct` deliberately absent.
      questions: questions.map(({ q, options, subject }) => ({ q, options, subject })),
    });
  } catch (err) { next(err); }
};

// ── 3A. AIBE — submit (deterministic, ZERO AI) ───────────────────────────────
const aibeSubmit = async (req, res, next) => {
  try {
    const { user_id, college_id } = req.user;
    const a = await loadOwnAttempt(req.body.paperId, user_id, college_id);
    if (!a || a.answers?.kind !== 'aibe') return res.status(404).json({ error: 'Paper not found.' });
    if (a.answers.submitted) return res.status(409).json({ error: 'This paper was already submitted.' });

    const qs = a.answers.questions || [];
    const chosen = Array.isArray(req.body.answers) ? req.body.answers : [];
    const t = timerVerdict(a.answers);

    let correctCount = 0;
    const bySubject = {};
    const results = qs.map((q, i) => {
      const raw = chosen[i];
      const n = raw === null || raw === undefined || raw === '' ? NaN : Number(raw);
      const pick = Number.isInteger(n) && n >= 0 && n <= 3 ? n : null;
      const isCorrect = pick !== null && pick === q.correct;
      if (isCorrect) correctCount++;
      bySubject[q.subject] = bySubject[q.subject] || { correct: 0, total: 0 };
      bySubject[q.subject].total++;
      if (isCorrect) bySubject[q.subject].correct++;
      return {
        q: q.q, options: q.options, subject: q.subject,
        correct: q.correct, chosen: pick, isCorrect,
      };
    });

    // AIBE has no negative marking — unattempted simply scores zero.
    const scorePct = qs.length ? Math.round((correctCount / qs.length) * 100) : 0;

    await queryAsCollege(
      college_id,
      `UPDATE exam_attempts SET answers=$2, score=$3
        WHERE attempt_id=$1 AND user_id=$4 AND college_id=$5`,
      [
        a.attempt_id,
        JSON.stringify({ ...a.answers, submitted: true, chosen, elapsed_sec: t.elapsedSec, expired: t.expired }),
        scorePct,
        user_id,
        college_id,
      ]
    );

    res.json({
      score: correctCount,
      total: qs.length,
      scorePct,
      passed: scorePct >= AIBE.passGeneralPct,
      passPct: AIBE.passGeneralPct,
      passReservedPct: AIBE.passReservedPct,
      attempted: results.filter((r) => r.chosen !== null).length,
      bySubject,
      results,
      expired: t.expired,
      elapsedSec: t.elapsedSec,
      durationMin: t.durationMin,
      disclaimer: DISCLAIMER,
    });
  } catch (err) { next(err); }
};

// ── 3B. SPPU — generate a full 80-mark paper ─────────────────────────────────
function sppuPrompt(programLabel, sem, subject) {
  const spec = SPPU.parts
    .map((p) => `Part ${p.part} (${p.label}): ${p.count} question(s), ${p.marks} marks each, answerable in about ${p.maxWords} words`)
    .join('\n');
  return `You are setting a Savitribai Phule Pune University (SPPU) written examination paper.
Subject: "${subject}" — ${programLabel}, Semester ${sem}.
Total marks: ${SPPU.totalMarks}. Duration: ${SPPU.durationMin} minutes.

Structure (follow exactly):
${spec}

Rules:
- Use CURRENT Indian law (BNS / BNSS / BSA, 2023) wherever the subject touches criminal law,
  procedure or evidence.
- Part A questions must require analysis or application, not recall.
- Part B are "write short notes on ..." style questions.
- Part C are direct short-answer questions.
- For EVERY question also give a brief marking scheme: the points a full-marks answer must cover.

Return STRICT JSON only, no prose, no markdown:
{"questions":[{"part":"A","q":"...","marks":15,"scheme":"..."}]}
Exactly ${SPPU_TOTAL_Q} questions, in part order A, B, C. JSON only.`;
}

const sppuGenerate = async (req, res, next) => {
  const { user_id, college_id } = req.user;
  try {
    const programId = PROGRAMS[req.body.program] ? req.body.program : null;
    const sem = Number(req.body.semester);
    const year = Number(req.body.year);
    const subject = String(req.body.subject || '');
    const valid = programId
      && Array.isArray(PROGRAMS[programId].sems[sem])
      && PROGRAMS[programId].sems[sem].includes(subject);
    if (!valid) return res.status(400).json({ error: 'Choose a valid program, semester and subject.' });

    const prompt = capTokens(sppuPrompt(PROGRAMS[programId].label, sem, subject), 900);
    let out;
    let genCalls = 1; // 2 if the truncation retry below fires
    // Same accounting rule as AIBE: the truncated first attempt is billed, so
    // its tokens must be carried into the log alongside the retry's.
    let genTin = 0, genTout = 0, genFinish = null;
    try {
      out = await generateText({ prompt, maxOutputTokens: 2400, temperature: 0.9, timeoutMs: 30000 });
      genTin += out.tokensIn || 0;
      genTout += out.tokensOut || 0;
      genFinish = out.finishReason || null;
      if (out.finishReason === 'MAX_TOKENS') {
        out = await generateText({ prompt, maxOutputTokens: 2900, temperature: 0.9, timeoutMs: 35000 });
        genCalls = 2;
        genTin += out.tokensIn || 0;
        genTout += out.tokensOut || 0;
        genFinish = worstFinish(genFinish, out.finishReason);
      }
    } catch (e) {
      console.error('SPPU generate failed:', e.message);
      return res.status(502).json({ error: 'Could not generate a paper right now. Please try again.' });
    }
    logUsage(user_id, college_id, out.model, genTin, genTout, genCalls, genFinish);

    let parsed;
    try {
      parsed = parseJson(out.text);
    } catch (e) {
      console.error('SPPU parse failed:', e.message);
      return res.status(502).json({ error: 'Could not generate a valid paper. Please try again.' });
    }

    // Rebuild the paper against OUR structure rather than trusting the model's
    // part labels and marks — the total has to be exactly 80 or the score lies.
    const byPart = { A: [], B: [], C: [] };
    for (const q of parsed.questions || []) {
      const p = String(q.part || '').toUpperCase();
      if (byPart[p]) byPart[p].push(q);
    }
    const questions = [];
    for (const spec of SPPU.parts) {
      for (let i = 0; i < spec.count; i++) {
        const q = byPart[spec.part][i];
        if (!q || !String(q.q || '').trim()) continue;
        questions.push({
          part: spec.part,
          q: String(q.q).slice(0, 700),
          marks: spec.marks,
          maxWords: spec.maxWords,
          scheme: String(q.scheme || '').slice(0, 900),
        });
      }
    }
    if (questions.length < SPPU_TOTAL_Q) {
      return res.status(502).json({ error: 'Could not build a complete paper. Please try again.' });
    }

    const meta = {
      kind: 'sppu',
      program: programId, year, sem, subject,
      questions, submitted: false,
      ...stamps(SPPU.durationMin),
    };
    const { rows } = await queryAsCollege(
      college_id,
      `INSERT INTO exam_attempts (user_id, college_id, exam_type, answers)
       VALUES ($1,$2,$3,$4) RETURNING attempt_id`,
      [user_id, college_id, `sppu:${programId}:${sem}`, JSON.stringify(meta)]
    );

    res.json({
      paperId: rows[0].attempt_id,
      program: PROGRAMS[programId].label,
      semester: sem,
      subject,
      totalMarks: SPPU.totalMarks,
      durationMin: SPPU.durationMin,
      expiresAt: meta.expires_at,
      practiceNote: PRACTICE_NOTE,
      disclaimer: DISCLAIMER,
      usedThisMonth: req.featureUsageCount ?? null,
      monthlyLimit: SPPU_MONTHLY_LIMIT,
      // `scheme` deliberately absent.
      questions: questions.map(({ part, q, marks, maxWords }) => ({ part, q, marks, maxWords })),
    });
  } catch (err) { next(err); }
};

// ── 3B. SPPU — submit → one AI grading call per answered question ────────────
const sppuSubmit = async (req, res, next) => {
  try {
    const { user_id, college_id } = req.user;
    const a = await loadOwnAttempt(req.body.paperId, user_id, college_id);
    if (!a || a.answers?.kind !== 'sppu') return res.status(404).json({ error: 'Paper not found.' });
    if (a.answers.submitted) return res.status(409).json({ error: 'This paper was already submitted.' });

    const qs = a.answers.questions || [];
    const answers = Array.isArray(req.body.answers) ? req.body.answers : [];
    const t = timerVerdict(a.answers);

    const graded = [];
    let awarded = 0, tinAll = 0, toutAll = 0, modelUsed = null;
    // One grading call per ANSWERED question, so this is anywhere from 0 (blank
    // paper, zero cost) to 8. Counted rather than assumed: unanswered questions
    // never reach Gemini.
    let callsAll = 0, lastFinish = null;

    for (let i = 0; i < qs.length; i++) {
      const q = qs[i];
      // Truncation happens HERE, before the text can reach Gemini — a student
      // pasting 5,000 words must not be able to inflate the bill.
      const answer = clampWords(answers[i] || '', q.maxWords);
      if (!answer.trim()) {
        graded.push({
          part: q.part, q: q.q, marks: q.marks, yourAnswer: '',
          awarded: 0, feedback: 'No answer submitted.', modelPoints: q.scheme,
        });
        continue;
      }

      const prompt = `You are an SPPU LLB examiner grading the subject "${a.answers.subject}".
Question (Part ${q.part}, ${q.marks} marks): ${q.q}
Marking scheme (what a full-marks answer must cover): ${q.scheme}
Student's answer: ${answer}

Award marks out of ${q.marks} and give brief, specific feedback naming what was missing.
Return STRICT JSON only: {"awarded":<0-${q.marks}>,"feedback":"<2-4 sentences>"}`;

      let g = null;
      try {
        const out = await generateText({
          prompt: capTokens(prompt, 1000),
          maxOutputTokens: 220,
          temperature: 0.2, // grading should be consistent, unlike generation
          timeoutMs: 20000,
        });
        tinAll += out.tokensIn || 0;
        toutAll += out.tokensOut || 0;
        callsAll += 1;
        lastFinish = worstFinish(lastFinish, out.finishReason);
        modelUsed = out.model || modelUsed;
        g = parseJson(out.text);
      } catch (e) {
        console.error('SPPU grade failed:', e.message);
        callsAll += 1; // attempted, possibly billed — do not undercount
      }

      // A grading failure must not silently become a zero — a zero reads as a
      // verdict on the student's answer. Say plainly that it wasn't graded.
      if (!g) {
        graded.push({
          part: q.part, q: q.q, marks: q.marks, yourAnswer: answer,
          awarded: null,
          feedback: 'This answer could not be graded automatically. It has not been counted against you.',
          modelPoints: q.scheme,
        });
        continue;
      }

      const mark = Math.max(0, Math.min(q.marks, Math.round(Number(g.awarded) || 0)));
      awarded += mark;
      graded.push({
        part: q.part, q: q.q, marks: q.marks, yourAnswer: answer,
        awarded: mark, feedback: String(g.feedback || '').slice(0, 700), modelPoints: q.scheme,
      });
    }

    if (tinAll || toutAll) logUsage(user_id, college_id, modelUsed, tinAll, toutAll, callsAll, lastFinish);

    // Ungradable questions are left out of the denominator so a Gemini outage
    // cannot drag a student's percentage down.
    const gradableMarks = graded.reduce((n, g) => n + (g.awarded === null ? 0 : g.marks), 0);
    const overallPct = gradableMarks ? Math.round((awarded / gradableMarks) * 100) : 0;

    await queryAsCollege(
      college_id,
      `UPDATE exam_attempts SET answers=$2, score=$3
        WHERE attempt_id=$1 AND user_id=$4 AND college_id=$5`,
      [
        a.attempt_id,
        JSON.stringify({ ...a.answers, submitted: true, graded, elapsed_sec: t.elapsedSec, expired: t.expired }),
        overallPct,
        user_id,
        college_id,
      ]
    );

    res.json({
      subject: a.answers.subject,
      awarded,
      outOf: SPPU.totalMarks,
      gradedOutOf: gradableMarks,
      overallPct,
      results: graded,
      expired: t.expired,
      elapsedSec: t.elapsedSec,
      durationMin: t.durationMin,
      disclaimer: DISCLAIMER,
    });
  } catch (err) { next(err); }
};

// ── 4. Library ───────────────────────────────────────────────────────────────
const libraryList = async (req, res, next) => {
  try {
    const program = PROGRAMS[req.query.program] ? req.query.program : null;
    if (!program) return res.status(400).json({ error: 'Choose a valid program.' });
    const year = req.query.year ? Number(req.query.year) : null;
    const sem = req.query.semester ? Number(req.query.semester) : null;

    const conds = ['program = $1', 'is_active'];
    const params = [program];
    if (Number.isInteger(year)) { params.push(year); conds.push(`year = $${params.length}`); }
    if (Number.isInteger(sem)) { params.push(sem); conds.push(`semester = $${params.length}`); }

    // exam_papers is shared platform content with no college_id and no RLS
    // policy — plain pool.query is correct here.
    const { rows } = await pool.query(
      `SELECT paper_id, program, year, semester, subject, exam_year, title
         FROM exam_papers
        WHERE ${conds.join(' AND ')}
        ORDER BY year, semester, subject, exam_year DESC NULLS LAST`,
      params
    );
    res.json({ program: PROGRAMS[program].label, papers: rows, links: LIBRARY_LINKS });
  } catch (err) { next(err); }
};

const libraryDownload = async (req, res, next) => {
  try {
    if (!BUCKET) return res.status(503).json({ error: 'Downloads are not configured yet.' });
    if (!UUID_RE.test(String(req.params.id || ''))) return res.status(404).json({ error: 'Paper not found.' });
    const { rows } = await pool.query(
      `SELECT s3_key, title FROM exam_papers WHERE paper_id=$1 AND is_active`,
      [req.params.id]
    );
    if (rows.length === 0) return res.status(404).json({ error: 'Paper not found.' });
    const url = await s3.getSignedUrlPromise('getObject', {
      Bucket: BUCKET,
      Key: rows[0].s3_key,
      Expires: 120,
      ResponseContentDisposition: `attachment; filename="${String(rows[0].title).replace(/[^\w.-]+/g, '_')}.pdf"`,
    });
    res.json({ url });
  } catch (err) { next(err); }
};

// ── 5. Analytics — pure SQL, zero AI ─────────────────────────────────────────
const getAnalytics = async (req, res, next) => {
  try {
    const { user_id, college_id } = req.user;
    const { rows } = await queryAsCollege(
      college_id,
      `SELECT attempt_id, exam_type, score, created_at
         FROM exam_attempts
        WHERE user_id=$1 AND college_id=$2 AND score IS NOT NULL
        ORDER BY created_at DESC
        LIMIT 50`,
      [user_id, college_id]
    );
    const scores = rows.map((r) => r.score).filter((s) => s !== null);
    res.json({
      attempts: rows,
      count: rows.length,
      average: scores.length ? Math.round(scores.reduce((x, y) => x + y, 0) / scores.length) : null,
      best: scores.length ? Math.max(...scores) : null,
    });
  } catch (err) { next(err); }
};

module.exports = {
  getStructure,
  getActive,
  aibeGenerate,
  aibeSubmit,
  sppuGenerate,
  sppuSubmit,
  libraryList,
  libraryDownload,
  getAnalytics,
};
